class TodoList {
  constructor(containerId) {
    this.container = document.querySelector(`#${containerId}`);
    this.todos = [];
    this.render();
  }

  addTodo(text) {
    if (!text.trim()) return;
    this.todos.push({ id: Date.now(), text: text.trim(), completed: false });
    this.render();
  }

  toggleTodo(id) {
    const todo = this.todos.find(t => t.id === id);
    if (todo) {
      todo.completed = !todo.completed;
      this.render();
    }
  }

  deleteTodo(id) {
    this.todos = this.todos.filter(t => t.id !== id);
    this.render();
  }

  createElement(tag, attributes = {}, children = []) {
    const el = document.createElement(tag);
    for (const [key, value] of Object.entries(attributes)) {
      if (key === "className") {
        el.className = value;
      } else if (key.startsWith("on")) {
        el.addEventListener(key.slice(2).toLowerCase(), value);
      } else {
        el.setAttribute(key, value);
      }
    }
    children.forEach(child => {
      if (typeof child === "string") {
        el.appendChild(document.createTextNode(child));
      } else {
        el.appendChild(child);
      }
    });
    return el;
  }

  render() {
    this.container.innerHTML = "";

    const header = this.createElement("h1", {}, ["Todo List"]);
    this.container.appendChild(header);

    const inputContainer = this.createElement("div", { className: "input-group" });
    const input = this.createElement("input", {
      type: "text",
      placeholder: "Add a new todo...",
      className: "todo-input"
    });
    const addBtn = this.createElement("button", { className: "add-btn" }, ["Add"]);
    addBtn.addEventListener("click", () => {
      this.addTodo(input.value);
      input.value = "";
    });
    inputContainer.appendChild(input);
    inputContainer.appendChild(addBtn);
    this.container.appendChild(inputContainer);

    const list = this.createElement("ul", { className: "todo-list" });
    this.todos.forEach(todo => {
      const li = this.createElement("li", {
        className: `todo-item ${todo.completed ? "completed" : ""}`
      });

      const checkbox = this.createElement("input", {
        type: "checkbox",
        checked: todo.completed
      });
      checkbox.addEventListener("change", () => this.toggleTodo(todo.id));

      const span = this.createElement("span", { className: "todo-text" }, [todo.text]);

      const deleteBtn = this.createElement("button", { className: "delete-btn" }, ["Delete"]);
      deleteBtn.addEventListener("click", () => this.deleteTodo(todo.id));

      li.appendChild(checkbox);
      li.appendChild(span);
      li.appendChild(deleteBtn);
      list.appendChild(li);
    });
    this.container.appendChild(list);
  }
}
